def symmetries(s):
    res=[]
    x=s
    for _ in range(4):
        res.append(x); res.append(np.fliplr(x)); res.append(np.flipud(x))
        x=np.rot90(x)
    # dedupe
    uniq=[]
    for m in res:
        if not any((m==u).all() for u in uniq): uniq.append(m)
    return uniq

def place(canvas, s, r0, c0, color):
    # returns dict cell->color for non-overlap, marks overlap
    d={}
    n=s.shape[0]
    for i in range(n):
        for j in range(n):
            if s[i,j]:
                r,c=r0+i,c0+j
                if 0<=r<canvas[0] and 0<=c<canvas[1]:
                    d[(r,c)]=color
    return d

