def solve_pair(S1, S2, col1, col2, target, H=7, W=7):
    sols=[]
    for m1 in symmetries(S1==S1):  # placeholder
        pass
    for m1 in symmetries((S1>0).astype(int)):
        for m2 in symmetries((S2>0).astype(int)):
            for r1 in range(-3,8):
                for c1 in range(-3,8):
                    d1=place((H,W),m1,r1,c1,col1)
                    for r2 in range(-3,8):
                        for c2 in range(-3,8):
                            d2=place((H,W),m2,r2,c2,col2)
                            # xor: overlap cancels
                            merged={}
                            ok=True
                            for k in set(d1)|set(d2):
                                a=k in d1; b=k in d2
                                if a and b: continue
                                merged[k]=d1.get(k,d2.get(k))
                            if merged==target:
                                sols.append((m1.copy(),(r1,c1),m2.copy(),(r2,c2)))
    return sols

