def solve_pair_op(S1,S2,col1,col2,target,ops=('xor','u1','u2','i1','i2')):
    sols=[]
    for m1 in symmetries((S1>0).astype(int)):
        for m2 in symmetries((S2>0).astype(int)):
            for r1 in range(-3,8):
                for c1 in range(-3,8):
                    d1=place((7,7),m1,r1,c1,col1)
                    if not d1: continue
                    for r2 in range(-3,8):
                        for c2 in range(-3,8):
                            d2=place((7,7),m2,r2,c2,col2)
                            if not d2: continue
                            both=set(d1)&set(d2)
                            for op in ops:
                                if op=='xor':
                                    if both: continue
                                    merged={**d2,**d1}
                                elif op=='u1': merged={**d2,**d1}
                                elif op=='u2': merged={**d1,**d2}
                                elif op=='i1':
                                    if not both: continue
                                    merged={k:d1[k] for k in both}
                                elif op=='i2':
                                    if not both: continue
                                    merged={k:d2[k] for k in both}
                                if merged==target:
                                    sols.append((op,m1.copy(),(r1,c1),m2.copy(),(r2,c2)))
    return sols

